-- 0036: Social kits — saved prompt sets from /admin/social.
--
-- A kit is one blog post's inputs (pulled from the Substack RSS feed or pasted)
-- and the ChatGPT prompts filled from src/lib/socialPrompts.js. Nothing here is
-- generated by a model: the site fills templates, the owner runs them in
-- ChatGPT. Kept so a post's prompts can be reopened, edited and copied again.
--
-- `template_version` is TEMPLATE_VERSION at the time the prompts were built: a
-- later template change does not rewrite a saved kit, and the page offers to
-- rebuild one made with an older version. `edited` marks prompts changed by
-- hand after building, which a rebuild would discard.
--
-- Owner-only, read and write, with no public policy at all: the post text is
-- public anyway, but the drafts and angles are not.

create table if not exists public.social_kits (
  id               bigint generated always as identity primary key,
  blog_url         text not null,
  url_key          text not null,
  title            text not null,
  subtitle         text,
  content          text,
  language         text not null default 'English' check (language in ('English', 'Marathi')),
  source           text not null default 'pasted' check (source in ('rss', 'pasted')),
  options          jsonb not null default '{}'::jsonb,
  prompts          jsonb not null default '{}'::jsonb,
  template_version int not null default 1,
  edited           boolean not null default false,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);

-- url_key is src/lib/htmlText.js normaliseUrl(): a Substack post matches on its
-- /p/<slug> whatever the host. One kit per post; saving again updates it.
create unique index if not exists social_kits_url_key_idx on public.social_kits (url_key);
create index if not exists social_kits_updated_at_idx on public.social_kits (updated_at desc);

drop trigger if exists set_updated_at on public.social_kits;
create trigger set_updated_at before update on public.social_kits
  for each row execute function public.set_updated_at();

alter table public.social_kits enable row level security;

drop policy if exists "social_kits owner all" on public.social_kits;
create policy "social_kits owner all" on public.social_kits for all
  to authenticated
  using (public.is_owner()) with check (public.is_owner());
